for c in C:
 script += [f"CHAPTER {c['number']}: {c['title']}", 'Learning outcome: '+c['objective'],'']
 for x in c['slides']:
  scenes.append(dict(id=x['id'],slide=len(scenes)+1,step=x['title'],text=x['text'],part=f"chapter-{c['number']:02d}",hold=3 if x['kind'] in ('choice','transfer','recall','practice') else 1))
  script += [x['id']+' | '+x['stage']+' | '+x['title'],x['text']]
  if 'quiz' in x:
   z=x['quiz']; script += [f"  {k+1}. {v}" for k,v in enumerate(z['options'])]+['  Suggested answer: '+str(z['correct']+1)]+['  Feedback: '+f for f in z['feedback']]
  if 'answers' in x:script += ['  Suggested recall: '+a for a in x['answers']]
  script += ['']
 script += ['Further reading:']+[r['title']+' — '+r['url'] for r in c['refs']]+['']
ROOT.joinpath('narration-script.txt').write_text('\n'.join(script))
ROOT.joinpath('production/scenes.json').write_text(json.dumps(scenes,ensure_ascii=False,indent=2))
